        self._collect_definitions(child, scope, resolution)

def _collect_arguments(
    self, op: Operation, scope: Scope, resolution: SymbolResolution
) -> None:
    kind = (
        SymbolKind.PORT
        if op.name in ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")
        else SymbolKind.ARGUMENT
    )
    for region in op.regions:
        for block in region.blocks:
            for index, argument in enumerate(block.arguments):
                name = argument.name or f"arg{index}"
                entry = scope.define(
                    SymbolEntry(name, kind, op=op, value=argument, type=argument.type)
                )
                resolution.values[entry.qualified_name] = entry

def _record_results(
    self, op: Operation, scope: Scope, resolution: SymbolResolution
) -> None:
    stateful = op.name.startswith("seq.") or op.name in ("firrtl.reg", "sv.reg")
    kind = SymbolKind.REGISTER if stateful else SymbolKind.VALUE
    for result in op.results:
        if not result.name:
            continue
        entry = scope.define(
            SymbolEntry(result.name, kind, op=op, value=result, type=result.type)
        )
        resolution.values[entry.qualified_name] = entry

@staticmethod
def _declared_type(op: Operation) -> Optional[Type]:
    attr = op.attributes.get("function_type")
    return attr.value if attr is not None else None

# -- references -------------------------------------------------------
def _collect_references(
    self, op: Operation, resolution: SymbolResolution
) -> None:
    def visit(candidate: Operation) -> None:
        for name in REFERENCE_ATTRIBUTES:
            attr = candidate.attributes.get(name)
            symbol = self._symbol_of(attr)
            if symbol is None:
                continue
            resolution.references.append(
                SymbolReference(symbol, candidate, attribute=name)
            )

    op.walk(visit)

@staticmethod
def _symbol_of(attr: Optional[Attribute]) -> Optional[str]:
    if isinstance(attr, FlatSymbolRefAttr):
        return str(attr.value)
    if isinstance(attr, StringAttr):
        return attr.value.lstrip("@")
    return None

def _bind_references(self, resolution: SymbolResolution) -> None:
    for ref in resolution.references:
        entry = resolution.lookup(ref.name)
        if entry is None:
            resolution.errors.append(
                f"unresolved symbol reference @{ref.name} in '{ref.user.name}'"
            )
            continue
        ref.target = entry.op

