    references: List[SymbolReference] = field(default_factory=list)
    values: Dict[str, SymbolEntry] = field(default_factory=dict)
    errors: List[str] = field(default_factory=list)

    # -- counts -----------------------------------------------------------
    @property
    def num_resolved(self) -> int:
        """How many symbol definitions were bound into the scope tree."""
        return len(self.definitions)

    @property
    def num_references(self) -> int:
        return len(self.references)

    @property
    def num_references_resolved(self) -> int:
        return sum(1 for ref in self.references if ref.is_resolved)

    @property
    def unresolved(self) -> List[SymbolReference]:
        return [ref for ref in self.references if not ref.is_resolved]

    @property
    def is_complete(self) -> bool:
        return not self.unresolved and not self.errors

    # -- lookup -----------------------------------------------------------
    def names(self) -> List[str]:
        return sorted(self.definitions)

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        key = name.lstrip("@%")
        return self.definitions.get(key) or self.root_scope.lookup(key)

    def operation(self, name: str) -> Optional[Operation]:
        entry = self.lookup(name)
        return entry.op if entry is not None else None

    def scope_for(self, name: str) -> Optional[Scope]:
        return self.root_scope.find_child(name.lstrip("@%"))

    def __len__(self) -> int:
        return len(self.definitions)

    def __contains__(self, name: str) -> bool:
        return self.lookup(name) is not None

    def to_text(self) -> str:
        lines: List[str] = []
        for scope in self.root_scope.walk():
            indent = "  " * scope.depth
            lines.append(f"{indent}{scope.name}:")
            for name in scope.names():
                lines.append(f"{indent}  {scope.entries[name]}")
        for ref in self.references:
            lines.append(str(ref))
        return "\n".join(lines)


